// ============================================
// UNIFIED METEO DECODER v3.0
// Gode di Strict Global Checking 
// ============================================

// ─── HELPER: Verifica Rigida delle Globali ───
function requireGlobal(key) {
    const val = global.get(key);
    if (val === undefined || val === null) {
        throw new Error(`[CRITICAL] Variabile globale mancante: ${key}`);
    }
    return val;
}

try {
    // --- 1. CARICAMENTO RIGIDO COSTANTI ---
    const PKT_MAGIC = requireGlobal("PKT_MAGIC");
    const PKT_VERSION = requireGlobal("PKT_VERSION");
    const HEADER_SIZE = requireGlobal("HEADER_SIZE");
    const PACKET_MIN_SIZE = requireGlobal("PACKET_MIN_SIZE");
    const ACK_OK = requireGlobal("ACK_OK");
    const ACK_END = requireGlobal("ACK_END");
    const ENC_TEMP_FACTOR = requireGlobal("ENC_TEMP_FACTOR");
    const ENC_TEMP_OFFSET = requireGlobal("ENC_TEMP_OFFSET");
    const ENC_HUM_FACTOR = requireGlobal("ENC_HUM_FACTOR");
    const ENC_PRESS_FACTOR = requireGlobal("ENC_PRESS_FACTOR");

    const TELEGRAM_CHAT_ID = -1001197831676;
    const ACK_TOPIC = "homie/espNowBridge/ack";
    // Status fallback se non esiste in globale (3 per errore)
    const ACK_ERROR = global.get("ACK_ERROR") || 3; 

    // ─── 2. HELPER INTERNI ───
    function buildBinaryAck(targetDeviceId, status) {
        const frame = Buffer.alloc(HEADER_SIZE + 2 + 1);
        frame[0] = PKT_MAGIC;
        frame[1] = PKT_VERSION;
        frame[2] = 0x00; // TYPE_ACK
        frame.writeUInt16LE(2, 3);
        frame[5] = targetDeviceId;
        frame[6] = status;

        let xor = 0;
        for (let i = 0; i < frame.length - 1; i++) xor ^= frame[i];
        frame[frame.length - 1] = xor;
        return frame;
    }

    function decodeMeteo(b) {
        if (b.length < 16) return null;
        let cXor = 0;
        for (let j = 0; j < 15; j++) cXor ^= b[j];
        if (cXor !== b[15]) return null;

        return {
            deviceId: b[0],
            humidity: b.readInt16LE(1) / ENC_HUM_FACTOR,
            temperature: (b.readInt16LE(3) / ENC_TEMP_FACTOR) - ENC_TEMP_OFFSET,
            pressure: b.readInt16LE(5) / ENC_PRESS_FACTOR,
            battery: b.readUInt16LE(7),
            moisture: b.readUInt16LE(9),
            counter: b[14]
        };
    }

    // ─── 3. LOGICA PRINCIPALE ───
    if (msg.topic !== "meteo/raw") return;

    const packetBuffer = msg.payload;
    const deviceId = msg.deviceId || (packetBuffer[5] || 0);

    if (!Buffer.isBuffer(packetBuffer) || packetBuffer.length < PACKET_MIN_SIZE) {
        throw new Error("Pacchetto malformato o non Buffer");
    }

    // Validazione globale XOR sul pacchetto
    let xor = 0;
    for (let i = 0; i < packetBuffer.length - 1; i++) xor ^= packetBuffer[i];
    if (xor !== packetBuffer[packetBuffer.length - 1]) {
        throw new Error("Checksum XOR fallito sull'intero pacchetto");
    }

    const payloadLength = packetBuffer.readUInt16LE(3);
    const payload = packetBuffer.slice(HEADER_SIZE, HEADER_SIZE + payloadLength);

    let records = [];

    if (payloadLength >= 64) {
        // MODALITÀ MULTI-RECORD (CHUNK)
        const totalRecords = payload.readUInt16LE(64);
        for (let i = 0; i < 4; i++) {
            let offset = i * 16;
            let record = decodeMeteo(payload.slice(offset, offset + 16));
            if (!record) throw new Error(`Checksum record fallito (offset ${offset})`);
            records.push(record);
        }

        const sessionKey = `meteoSync_${deviceId}`;
        let session = flow.get(sessionKey) || { received: [], total: totalRecords };

        session.received.push(...records);
        session.total = totalRecords; 
        flow.set(sessionKey, session);

        node.warn(`📦 [MULTI] Chunk ricevuto: ${session.received.length}/${session.total} record`);

        if (session.received.length < session.total) {
            // Sessione non finita, emetti ACK_OK su output 3 per chiedere il prossimo
            const ackOk = buildBinaryAck(deviceId, ACK_OK);
            return [null, null, { topic: ACK_TOPIC, payload: ackOk }];
        }

        // Sessione completata
        records = session.received.reverse();
        flow.set(sessionKey, null);
        node.warn(`✅ [MULTI] Sync di ${records.length} record completata, invio al cloud...`);

    } else {
        // MODALITÀ SINGLE-RECORD
        node.warn(`📦 [SINGLE] Record meteo singolo ricevuto, invio al cloud...`);
        let record = decodeMeteo(payload.slice(0, 16));
        if (!record) throw new Error("Checksum error su record singolo");
        records.push(record);
    }

    // ─── 4. MAPPING HTTP VERSO ALTERVISTA ───
    // (Corretto anche il bug delle variabili undefined per temperatura e pressione)
    const httpMsg = {
        payload: records.map(r => ({
            deviceId: r.deviceId,
            temperatureBMP: r.temperature,  // <-- Corretto da r.temperatureBMP errato
            externalPressure: r.pressure,   // <-- Corretto da r.externalPressure errato
            humidityBMP: r.humidity,        // <-- Corretto da r.humidityBMP errato
            voltage: r.battery,
            moisture: r.moisture,
            counter: r.counter
        })),
        originalData: {  // salvataggio per backup e ack down-stream
            deviceId: deviceId,
            records: records
        }
    };

    // Ritorna [HTTP_Req_Node, Telegram_Node, ACK_MQTT_Node]
    // L'ACK end finale qui è NULL perché delegato al response handler HTTP!
    return [httpMsg, null, null];

} catch (err) {
    node.error(`ERRORE METEO DECODER: ${err.message}`);
    const teleMsg = {
        payload: {
            chatId: -1001197831676,
            type: 'message',
            content: `🚨 ERRORE METEO DECODER: ${err.message}`
        }
    };

    // Ritorno l'errore verso Telegram, e chiudo con NULL verso gli altri.
    return [null, teleMsg, null];
}

// ============================================
// HTTP HANDLER & FINAL ACK MAKER
// Decide il fato della sonda meteo in base all'HTTP
// ============================================

function requireGlobal(key) {
    const val = global.get(key);
    if (val === undefined || val === null) {
        throw new Error(`[CRITICAL] Variabile globale mancante: ${key}`);
    }
    return val;
}

try {
    const PKT_MAGIC = requireGlobal("PKT_MAGIC");
    const PKT_VERSION = requireGlobal("PKT_VERSION");
    const HEADER_SIZE = requireGlobal("HEADER_SIZE");
    const ACK_END = requireGlobal("ACK_END");
    const ACK_FAILED = global.get("ACK_FAILED") || 3;

    function buildBinaryAck(targetDeviceId, status) {
        const frame = Buffer.alloc(HEADER_SIZE + 2 + 1);
        frame[0] = PKT_MAGIC;
        frame[1] = PKT_VERSION;
        frame[2] = 0x00; // TYPE_ACK
        frame.writeUInt16LE(2, 3);
        frame[5] = targetDeviceId;
        frame[6] = status;

        let xor = 0;
        for (let i = 0; i < frame.length - 1; i++) xor ^= frame[i];
        frame[frame.length - 1] = xor;
        return frame;
    }

    const statusCode = msg.statusCode;
    const originalData = msg.originalData || {};
    const deviceId = originalData.deviceId || msg.deviceId || 0;
    const records = originalData.records || [];

    let telegramMsg = null;
    let backupDataMsg = null;
    let finalAckMsg = null;

    if (statusCode === 200 || statusCode === 201) {
        node.warn(`✅ Cloud Salvato OK! Emetto ACK_END.`);
        finalAckMsg = {
            topic: "homie/espNowBridge/ack",
            payload: buildBinaryAck(deviceId, ACK_END)
        };

    } else {
        node.error(`❌ Cloud client error: ${statusCode}. Emetto ACK_FAILED.`);
        backupDataMsg = {
            payload: {
                deviceId: deviceId,
                records: records,
                reason: `http_fail_${statusCode}`,
                httpStatus: statusCode
            }
        };
        telegramMsg = {
            payload: {
                chatId: -1001197831676,
                type: 'message',
                content: `⚠️ CLOUD ERROR: Sonda ${deviceId.toString(16)} - HTTP ${statusCode}`
            }
        };
        finalAckMsg = {
            topic: "homie/espNowBridge/ack",
            payload: buildBinaryAck(deviceId, ACK_FAILED)
        };
    }

    // Return order: [Telegram Node, Backup Node, MQTT ACK Node]
    return [telegramMsg, backupDataMsg, finalAckMsg];

} catch (err) {
    node.error(`ERRORE IN HTTP HANDLER: ${err.message}`);
    return [null, null, null];
}

const fs = require('fs');
const BACKUP_DIR = "/mnt/f2fs/meteo_backups";

try {
    if (!fs.existsSync(BACKUP_DIR)) {
        fs.mkdirSync(BACKUP_DIR, { recursive: true });
    }

    const data = msg.payload;
    const timestamp = Date.now();
    const filename = `${BACKUP_DIR}/meteo_${data.deviceId.toString(16)}_${timestamp}.json`;

    fs.writeFileSync(filename, JSON.stringify({
        ...data,
        timestamp: timestamp,
        recordsCount: data.records ? data.records.length : 0
    }, null, 2));

    node.warn(`💾 Backup salvato: ${filename}`);
} catch (err) {
    node.error(`Errore IO backup: ${err.message}`);
}

return null;
